		protected global::NexAssets.Common.ASYNCSTATE ExecAfterLogin(global::NexAssets.Common.CORE_ARG coreArg) {
            s_AutoLoginState = ASYNCSTATE.NONE;
            s_AutoLoginResult = new AsyncResult();
            if (!s_NexInitParam.autoLogin || (coreArg.pNgsFacade != IntPtr.Zero && NgsFacade.IsConnected(coreArg.pNgsFacade).IsSuccess()))
                return coreArg.func(null, coreArg);

            uint asyncId = 0;
            s_AutoLoginState = InitializeNexsInf(ref asyncId);
            if (s_AutoLoginState == ASYNCSTATE.NGS_LOGIN_START || s_AutoLoginState == ASYNCSTATE.INIT_NEX_START)
            {
                coreArg.asyncId = asyncId;
                s_CoreArgList.Add(coreArg);
            }
            else if (IsAsyncStateError(s_AutoLoginState)) // inlined (mask 0xbf8a @01f841f4)
            {
                s_AutoLoginResult.errorCode = 0x80000000;
                s_CoreArgList.Remove(coreArg);
                coreArg.func(s_AutoLoginResult, coreArg);
