		private void CoreInitCB(global::NexPlugin.AsyncResult asyncResult) {
            s_AutoLoginResult = asyncResult;
            if (asyncResult.IsFailure())
                s_AutoLoginState = ASYNCSTATE.INIT_NEX_ERROR;
            CORE_ARG coreArg = s_CoreArgList.Find(arg => arg.asyncId == asyncResult.asyncId);
            if (coreArg == null)
                return;
            NC_LOG("CoreInitCB: {0} : {1}", new object[] { s_AutoLoginState, asyncResult.ToString() });
            if (s_AutoLoginState != ASYNCSTATE.INIT_NEX_ERROR)
            {
                s_AutoLoginState = NGSLoginInf(ref coreArg.asyncId);
                if (s_AutoLoginState == ASYNCSTATE.NGS_LOGIN_START)
                    return;
                s_AutoLoginResult.errorCode = 0x80000000;
            }
            s_CoreArgList.Remove(coreArg);
            coreArg.func(s_AutoLoginResult, coreArg);
        }
		private void CoreLoginCB(global::NexPlugin.AsyncResult asyncResult, ulong pid, global::System.IntPtr pNgsFacade) {
            s_AutoLoginResult = asyncResult;
            SetDefaultUser(pNgsFacade); // inlined through slot 0x4b9c868 → 0x4cbd29d (@01f86720–01f86778)
            NC_LOG("PID: {0}", new object[] { pid });
            CORE_ARG coreArg = s_CoreArgList.Find(arg => arg.asyncId == asyncResult.asyncId);
            NC_LOG("CoreLoginCB() coreArg: {0}", new object[] { coreArg });
            if (coreArg == null)
                return;
            NC_LOG("CoreLoginCB() asyncResult: {0}", new object[] { asyncResult });
            if (asyncResult.IsSuccess())
                s_AutoLoginState = ASYNCSTATE.PLUGINCALL_SUCCESS;
            s_CoreArgList.Remove(coreArg);
            coreArg.pNgsFacade = pNgsFacade;
            if (coreArg.func(asyncResult, coreArg) == ASYNCSTATE.PLUGINCALL_ERROR && s_AutoLoginState == ASYNCSTATE.PLUGINCALL_SUCCESS)
            {
                asyncResult.asyncNum = coreArg.asyncNum;
                asyncResult.returnCode = 0;
                asyncResult.errorCode = 0x80000000;
                coreArg.func(asyncResult, coreArg);
            }
        }
