		protected static int GetCallCount(global::NexAssets.Common.FunctionInfo info, global::System.Collections.Generic.List<global::NexAssets.Common.ApiCallsFrequency> list) {
            // apiCall is captured (display class +0x28) and written field by field in place (@01f86b90–01f86b9c)
            ApiCallsFrequency apiCall = new ApiCallsFrequency();
            apiCall.type = info.type;
            apiCall.time = Time.realtimeSinceStartup;
            list.Insert(0, apiCall);
            list.RemoveAll(x => x.type == info.type && apiCall.time - x.time > info.time);
            return list.FindAll(x => x.type == info.type).Count;
        }
